package com.yuegang.zhihui.ai.infrastructure;import com.yuegang.zhihui.ai.domain.*;import com.yuegang.zhihui.common.core.ApiResponse;import com.yuegang.zhihui.common.security.InternalServiceSignature;import com.yuegang.zhihui.search.api.*;import java.time.*;import java.util.*;import org.springframework.web.client.RestClient;public final class HttpRetrievalGateway implements RetrievalGateway{private static final String PATH="/internal/v1/search/hybrid";private final RestClient client;private final InternalServiceSignature signatures;public HttpRetrievalGateway(String base,byte[]secret){client=RestClient.builder().baseUrl(base).build();signatures=new InternalServiceSignature(secret,Clock.systemUTC(),Duration.ofSeconds(30));}public List<SearchHit>search(String q,String c,int limit){Instant now=Instant.now();var metadata=new InternalServiceSignature.Metadata("ygh-ai-service","POST",PATH,now);@SuppressWarnings("unchecked")ApiResponse<List<Map<String,Object>>>r=client.post().uri(PATH).header("X-YGH-Service","ygh-ai-service").header("X-YGH-Service-Timestamp",Long.toString(now.toEpochMilli())).header("X-YGH-Service-Signature",signatures.sign(metadata)).body(new SearchRequest(q,limit,c)).retrieve().body(ApiResponse.class);if(r==null||r.data()==null)return List.of();return r.data().stream().map(x->new SearchHit(Objects.toString(x.get("documentId")),Objects.toString(x.get("chunkId")),Objects.toString(x.get("title")),Objects.toString(x.get("excerpt")),number(x.get("lexicalScore")),number(x.get("vectorScore")),number(x.get("finalScore")))).toList();}private static double number(Object v){return v instanceof Number n?n.doubleValue():0;}}
